import type { Metadata } from "next";
import { TeamMembers } from "./team-members";

export const metadata: Metadata = {
  title: "Team",
};

export default function TeamPage() {
  return (
    <main className="flex min-h-svh items-start justify-center bg-muted/40 p-6 md:p-10">
      <div className="w-full max-w-3xl">
        <TeamMembers />
      </div>
    </main>
  );
}

import { type CnOptions, cn as mergeClasses } from "tailwind-variants";

export function cn(...classes: CnOptions): string {
  return mergeClasses(...classes) ?? "";
}

"use client";

import { UserIcon } from "@phosphor-icons/react";
import { type ComponentProps, useState } from "react";
import { tv, type VariantProps } from "tailwind-variants";
import { cn } from "./utils";

const avatarStyles = tv({
  base: "inline-grid shrink-0 place-items-center overflow-hidden rounded-full bg-accent font-semibold leading-none text-accent-foreground ring-1 ring-border/70 select-none *:col-start-1 *:row-start-1 forced-colors:border",
  variants: {
    size: {
      xs: "size-6 text-[0.5625rem]",
      sm: "size-8 text-[0.6875rem]",
      md: "size-10 text-xs",
      lg: "size-12 text-sm",
      xl: "size-16 text-lg",
    },
  },
  defaultVariants: { size: "md" },
});

export interface AvatarProps extends ComponentProps<"span"> {
  name: string;
  src?: string;
  initials?: string;
  size?: NonNullable<VariantProps<typeof avatarStyles>["size"]>;
}

export function Avatar({
  name,
  src,
  initials,
  size = "md",
  className,
  ...props
}: AvatarProps) {
  const [loadedSrc, setLoadedSrc] = useState<string | undefined>();
  const [failedSrc, setFailedSrc] = useState<string | undefined>();
  const showImage = Boolean(src && src !== failedSrc);
  const imageLoaded = showImage && src === loadedSrc;
  const fallback =
    initials ??
    name
      .trim()
      .split(/\s+/)
      .map((part) => part.match(/[\p{L}\p{N}]/u)?.[0])
      .filter(Boolean)
      .slice(0, 2)
      .join("")
      .toLocaleUpperCase();

  return (
    <span
      {...props}
      role="img"
      aria-label={name}
      data-slot="avatar"
      data-size={size}
      className={avatarStyles({ size, className })}
    >
      {!imageLoaded && (
        <span aria-hidden="true" data-slot="avatar-fallback">
          {fallback || <UserIcon className="block size-[1.6em]" />}
        </span>
      )}
      {showImage && (
        // biome-ignore lint/performance/noImgElement: Keep the avatar usable outside Next.js.
        <img
          ref={(image) => {
            if (!image?.complete) return;
            if (image.naturalWidth > 0) setLoadedSrc(src);
            else setFailedSrc(src);
          }}
          src={src}
          alt=""
          data-slot="avatar-image"
          className="size-full object-cover"
          onLoad={() => setLoadedSrc(src)}
          onError={() => setFailedSrc(src)}
        />
      )}
    </span>
  );
}

export function AvatarGroup({ className, ...props }: ComponentProps<"div">) {
  return (
    // biome-ignore lint/a11y/useSemanticElements: Avatars are not form controls.
    <div
      role="group"
      data-slot="avatar-group"
      className={cn(
        "flex flex-wrap items-center gap-y-1 -space-x-2 [&_[data-slot=avatar]]:ring-2 [&_[data-slot=avatar]]:ring-background",
        className,
      )}
      {...props}
    />
  );
}

import { Children, type HTMLAttributes, type ReactNode } from "react";
import { tv, type VariantProps } from "tailwind-variants";
import { cn } from "./utils";

const badgeStyles = tv({
  base: "inline-flex min-h-6 w-fit min-w-0 max-w-full shrink-0 items-center gap-1.5 overflow-hidden whitespace-nowrap rounded-full px-2.5 py-0.5 text-xs font-medium leading-4 tracking-normal shadow-[var(--shadow-card)] ring-1 forced-colors:border [&_svg]:pointer-events-none [&_svg]:shrink-0",
  variants: {
    variant: {
      neutral: "bg-secondary text-secondary-foreground ring-border",
      accent: "bg-accent text-accent-foreground ring-primary/15",
      success: "bg-success-subtle text-success-foreground ring-success/15",
      warning: "bg-warning-subtle text-warning-foreground ring-warning/20",
      error: "bg-card text-destructive ring-destructive/25",
      outline: "bg-transparent text-foreground ring-border",
    },
  },
  defaultVariants: { variant: "neutral" },
});

export interface BadgeProps extends HTMLAttributes<HTMLSpanElement> {
  variant?: NonNullable<VariantProps<typeof badgeStyles>["variant"]>;
  dot?: boolean;
}

function badgeLabel(children: ReactNode): ReactNode {
  const parts: ReactNode[] = [];
  let text = "";
  const flush = () => {
    if (text.trim()) {
      parts.push(
        <span
          key={`label-${parts.length}`}
          data-slot="badge-label"
          className="min-w-0 truncate"
        >
          {text}
        </span>,
      );
    }
    text = "";
  };
  for (const child of Children.toArray(children)) {
    if (typeof child === "string" || typeof child === "number") {
      text += child;
    } else {
      flush();
      parts.push(child);
    }
  }
  flush();
  return parts;
}

export function Badge({
  variant = "neutral",
  dot = false,
  className,
  children,
  ...props
}: BadgeProps) {
  return (
    <span
      data-slot="badge"
      data-variant={variant}
      className={badgeStyles({ variant, className })}
      {...props}
    >
      {dot && <BadgeDot />}
      {badgeLabel(children)}
    </span>
  );
}

export function BadgeDot({
  className,
  ...props
}: HTMLAttributes<HTMLSpanElement>) {
  return (
    <span
      aria-hidden="true"
      {...props}
      data-slot="badge-dot"
      className={cn(
        "size-1.5 shrink-0 rounded-full bg-current forced-colors:bg-[CanvasText]",
        className,
      )}
    />
  );
}

import type { Transition } from "motion/react";

export const easeOut = [0.23, 1, 0.32, 1] as const;

export const easeInOut = [0.77, 0, 0.175, 1] as const;

export const duration = {
  fast: 0.14,
  base: 0.2,
  slow: 0.28,
} as const;

export const springSnappy = {
  type: "spring",
  duration: 0.24,
  bounce: 0,
} as const satisfies Transition;

export const springLayout = {
  type: "spring",
  duration: 0.3,
  bounce: 0,
} as const satisfies Transition;

export function transitionFor(
  reduceMotion: boolean | null,
  transition: Transition,
): Transition {
  return reduceMotion ? { duration: 0 } : transition;
}

import { Children, type ReactNode } from "react";
import { tv, type VariantProps } from "tailwind-variants";

export function buttonLabel(children: ReactNode): ReactNode {
  const parts: ReactNode[] = [];
  let text = "";
  const flush = () => {
    if (text.trim()) {
      parts.push(
        <span
          key={`label-${parts.length}`}
          data-slot="button-label"
          className="min-w-0 truncate"
        >
          {text}
        </span>,
      );
    }
    text = "";
  };
  for (const child of Children.toArray(children)) {
    if (typeof child === "string" || typeof child === "number") {
      text += child;
    } else {
      flush();
      parts.push(child);
    }
  }
  flush();
  return parts;
}

export const touchTarget =
  "relative pointer-coarse:after:absolute pointer-coarse:after:inset-x-0 pointer-coarse:after:top-1/2 pointer-coarse:after:h-[max(100%,var(--touch-target,2.75rem))] pointer-coarse:after:-translate-y-1/2";

export const buttonStyles = tv({
  base: "inline-flex min-w-0 max-w-full shrink-0 cursor-default items-center justify-center whitespace-nowrap rounded-md font-medium tracking-[-0.01em] outline-offset-4 outline-transparent transition-[color,background-color,border-color,box-shadow,scale,outline-color,outline-offset] duration-150 ease-out-quint disabled:cursor-default disabled:opacity-50 disabled:shadow-none focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring motion-reduce:outline-offset-2 [&_svg]:pointer-events-none [&_svg]:shrink-0",
  variants: {
    variant: {
      default:
        "bg-primary text-primary-foreground shadow-[var(--shadow-card)] hover:bg-primary/90 pressed:bg-primary/90",
      secondary:
        "bg-secondary text-secondary-foreground hover:bg-border/70 pressed:bg-border/70",
      outline:
        "border border-border bg-card text-foreground shadow-[var(--shadow-card)] hover:bg-muted pressed:bg-muted",
      ghost:
        "text-foreground hover:bg-muted in-data-[item-highlight=under]:hover:bg-transparent pressed:bg-muted aria-[pressed=true]:bg-accent aria-[pressed=true]:text-accent-foreground aria-[pressed=true]:hover:bg-accent",
      minimal:
        "text-muted-foreground hover:bg-muted in-data-[item-highlight=under]:hover:bg-transparent hover:text-foreground pressed:bg-muted pressed:text-foreground",
      destructive:
        "bg-destructive text-background shadow-[var(--shadow-card)] hover:bg-destructive/90 pressed:bg-destructive/90",
    },
    size: {
      xs: `h-7 gap-1.5 rounded-sm px-2.5 text-xs [&_svg:not([class*='size-'])]:size-3.5 ${touchTarget}`,
      sm: `h-9 gap-2 px-3.5 text-sm [&_svg:not([class*='size-'])]:size-4 ${touchTarget}`,
      md: "h-11 gap-2 px-5 text-sm [&_svg:not([class*='size-'])]:size-4",
      lg: "h-12 gap-2 px-6 text-sm [&_svg:not([class*='size-'])]:size-4",
      xl: "h-14 gap-2.5 rounded-lg px-7 text-base [&_svg:not([class*='size-'])]:size-5",
    },
    iconOnly: {
      true: "cursor-pointer px-0",
    },
  },
  compoundVariants: [
    { size: "xs", iconOnly: true, class: "w-7" },
    { size: "sm", iconOnly: true, class: "w-9" },
    {
      size: "md",
      iconOnly: true,
      class: "w-11 [&_svg:not([class*='size-'])]:size-4.5",
    },
    {
      size: "lg",
      iconOnly: true,
      class: "w-12 [&_svg:not([class*='size-'])]:size-5",
    },
    {
      size: "xl",
      iconOnly: true,
      class: "w-14 [&_svg:not([class*='size-'])]:size-6",
    },
  ],
  defaultVariants: { variant: "default", size: "md" },
});

export const buttonLinkStyles = tv({
  extend: buttonStyles,
  base: "cursor-pointer",
});

export type ButtonVariant = NonNullable<
  VariantProps<typeof buttonStyles>["variant"]
>;

"use client";

import { createContext, type ReactNode, useContext } from "react";

export type Size = "xs" | "sm" | "md" | "lg" | "xl";

const SizeContext = createContext<Size | undefined>(undefined);

export function useSize(size?: Size) {
  const inherited = useContext(SizeContext);
  return size ?? inherited;
}

export function SizeProvider({
  size,
  children,
}: {
  size: Size | undefined;
  children: ReactNode;
}) {
  return <SizeContext value={size}>{children}</SizeContext>;
}

"use client";

import { type MotionProps, motion, useReducedMotion } from "motion/react";
import {
  Button as AriaButton,
  type ButtonProps as AriaButtonProps,
  composeRenderProps,
} from "react-aria-components";
import { springLayout } from "./motion";
import { type ButtonVariant, buttonLabel, buttonStyles } from "./button-styles";
import { type Size, useSize } from "./size";

export interface ButtonProps
  extends Omit<
    AriaButtonProps,
    | "style"
    | "onAnimationStart"
    | "onAnimationEnd"
    | "onAnimationIteration"
    | "onHoverStart"
    | "onHoverEnd"
  > {
  ref?: React.Ref<HTMLButtonElement>;
  variant?: ButtonVariant;
  size?: Size;
  iconOnly?: boolean;
  static?: boolean;
  layout?: MotionProps["layout"];
}

const MotionButton = motion.create(AriaButton);

const pressStyles = "motion-safe:pressed:not-aria-expanded:scale-[0.96]";

export function Button({
  className,
  children,
  variant = "default",
  size: sizeProp,
  iconOnly = false,
  static: isStatic = false,
  layout,
  ...props
}: ButtonProps) {
  const reduceMotion = useReducedMotion();
  const size = useSize(sizeProp) ?? "md";
  return (
    <MotionButton
      data-slot="button"
      data-variant={variant}
      data-size={size}
      data-icon-only={iconOnly || undefined}
      layout={reduceMotion ? false : layout}
      transition={springLayout}
      className={composeRenderProps(className, (className) =>
        buttonStyles({
          variant,
          size,
          iconOnly,
          className: [!isStatic && pressStyles, className],
        }),
      )}
      {...props}
    >
      {composeRenderProps(children, buttonLabel)}
    </MotionButton>
  );
}

